def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def _clip_move(dx, dy):
        if dx > 1:
            dx = 1
        elif dx < -1:
            dx = -1
        if dy > 1:
            dy = 1
        elif dy < -1:
            dy = -1
        return [dx, dy]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pos(observation.get("self_position"))
    ox, oy = _pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return _clip_move(_step(sx, ox), _step(sy, oy))
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        best = corners[0]
        best_dist = -1
        for cx, cy in corners:
            d = abs(cx - ox) + abs(cy - oy)
            if d > best_dist:
                best_dist = d
                best = (cx, cy)
        return _clip_move(_step(sx, best[0]), _step(sy, best[1]))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        if not targets:
            return [0, 0]
        best = None
        best_score = None
        for item in targets:
            tx, ty = _pos(item, None)
            if tx is None:
                continue
            score = abs(tx - sx) + abs(ty - sy)
            if best_score is None or score < best_score:
                best_score = score
                best = (tx, ty)
        if best is None:
            return [0, 0]
        return _clip_move(_step(sx, best[0]), _step(sy, best[1]))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = None
        for item in resources:
            rx, ry = _pos(item, None)
            if rx is None:
                continue
            score = abs(rx - sx) + abs(ry - sy)
            if best_score is None or score < best_score:
                best_score = score
                best = (rx, ry)
        if best is not None:
            return _clip_move(_step(sx, best[0]), _step(sy, best[1]))

    if ox != sx or oy != sy:
        return _clip_move(_step(sx, ox), _step(sy, oy))
    return [0, 0]

